<script setup>
import { ref, computed, onUnmounted } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputPhone from '@/components/Input/InputPhone.vue'

// Real-world scenario state
const rcWaCode = ref('62')
const rcWaNum = ref('81234567890')
const rcOfficeCode = ref('021')
const rcOfficeNum = ref('3155555')
const generatedOtp = ref('')
const otpCooldown = ref(0)
let timerInterval = null

function resetScenarioData() {
  rcWaCode.value = ''
  rcWaNum.value = ''
  rcOfficeCode.value = ''
  rcOfficeNum.value = ''
  generatedOtp.value = ''
}

function loadScenarioData() {
  rcWaCode.value = '62'
  rcWaNum.value = '82198765432'
  rcOfficeCode.value = '021'
  rcOfficeNum.value = '3901234'
}

function setPreset(code, num) {
  rcWaCode.value = code
  rcWaNum.value = num
}

function sendOtpSimulation() {
  if (otpCooldown.value > 0) return
  // Generate 6 digit OTP
  const code = Math.floor(100000 + Math.random() * 900000)
  generatedOtp.value = `${code.toString().substring(0, 3)} ${code.toString().substring(3, 6)}`
  otpCooldown.value = 60

  clearInterval(timerInterval)
  timerInterval = setInterval(() => {
    if (otpCooldown.value > 0) {
      otpCooldown.value--
    } else {
      clearInterval(timerInterval)
    }
  }, 1000)
}

onUnmounted(() => {
  clearInterval(timerInterval)
})

// Telco Operator & Format Resolver
const telcoInfo = computed(() => {
  const code = String(rcWaCode.value || '').trim()
  const num = String(rcWaNum.value || '').trim()

  if (!num) {
    return {
      isValid: false,
      operator: 'Menunggu Nomor',
      formattedE164: '-',
      message: 'Masukkan nomor WhatsApp nasabah'
    }
  }

  // Format E.164
  const formattedE164 = `+${code || '62'} ${num}`

  // Detect Operator
  let operator = 'Operator Seluler Lainnya'
  const prefix4 = num.startsWith('0') ? num.substring(0, 4) : '0' + num.substring(0, 3)

  if (['0811', '0812', '0813', '0821', '0822', '0823', '0851', '0852', '0853'].includes(prefix4)) {
    operator = 'Telkomsel (Halo / SimPATI / By.U)'
  } else if (['0814', '0815', '0816', '0855', '0856', '0857', '0858'].includes(prefix4)) {
    operator = 'Indosat Ooredoo (IM3)'
  } else if (['0817', '0818', '0819', '0859', '0877', '0878'].includes(prefix4)) {
    operator = 'XL Axiata / Axis'
  } else if (['0895', '0896', '0897', '0898', '0899'].includes(prefix4)) {
    operator = 'Tri (3 Indonesia)'
  } else if (['0881', '0882', '0883', '0884', '0885', '0886', '0887', '0888'].includes(prefix4)) {
    operator = 'Smartfren'
  }

  const isValid = num.length >= 8

  return {
    isValid,
    operator,
    formattedE164,
    message: isValid
      ? `Nomor siap menerima pesan notifikasi resmi via ${operator}`
      : 'Panjang nomor belum mencukupi standar seluler'
  }
})

// Lifecycle states
const codeDefault = ref('')
const numDefault = ref('')
const codeMobile = ref('62')
const numMobile = ref('81234567890')
const codeRequired = ref('')
const numRequired = ref('')

// Props Matrix Documentation
const phoneProps = [
  {
    name: 'label',
    type: 'String',
    default: "''",
    description: 'Teks label utama di atas kelompok input nomor telepon.'
  },
  {
    name: 'phoneCodeLength',
    type: 'Number',
    default: '4',
    description: 'Batas maksimum digit kode area sebelum auto-focus berpindah ke nomor lokal.'
  },
  {
    name: 'required',
    type: 'Boolean',
    default: 'false',
    description: 'Menandai nomor telepon wajib diisi pada formulir.'
  },
  {
    name: 'eror',
    type: 'String',
    default: "''",
    description: 'Pesan kesalahan validasi kustom (sesuai nama prop implementasi library eror).'
  },
  {
    name: 'v-model:phone-code',
    type: 'String',
    description: 'Two-way data binding untuk nilai segmen kode area / negara.'
  },
  {
    name: 'v-model:phone-number',
    type: 'String',
    description: 'Two-way data binding untuk nilai segmen nomor telepon lokal.'
  },
  {
    name: '#label-icon',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot untuk menyisipkan ikon atau tooltip di samping teks label.'
  },
  {
    name: '@update:phone-code',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat pengguna mengedit segmen kode negara/area.'
  },
  {
    name: '@update:phone-number',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat pengguna mengedit segmen nomor telepon utama.'
  }
]
</script>
