<script setup>
defineOptions({
  name: 'DatePickerSection'
})
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import DatePicker from '@/components/Dropdown/DatePicker.vue'

// Real-world scenario state
const rcTanggalLelang = ref('2026-09-28')

function resetScenarioData() {
  rcTanggalLelang.value = ''
}

function loadScenarioData() {
  rcTanggalLelang.value = '2026-10-15'
}

function subDays(dateStr, days) {
  if (!dateStr) return null
  const d = new Date(dateStr)
  if (isNaN(d.getTime())) return null
  d.setDate(d.getDate() - days)
  return d
}

function formatIndo(dateObj) {
  if (!dateObj) return '-'
  return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }).format(dateObj)
}

const formattedAuctionDate = computed(() => {
  if (!rcTanggalLelang.value) return 'Belum ditentukan'
  const d = new Date(rcTanggalLelang.value)
  return isNaN(d.getTime()) ? '-' : formatIndo(d)
})

const spDateText = computed(() => {
  return formatIndo(subDays(rcTanggalLelang.value, 14))
})

const announcementDateText = computed(() => {
  return formatIndo(subDays(rcTanggalLelang.value, 7))
})

const revaluationDateText = computed(() => {
  return formatIndo(subDays(rcTanggalLelang.value, 2))
})

const countdownBadgeText = computed(() => {
  if (!rcTanggalLelang.value) return 'Belum Dijadwalkan'
  const target = new Date(rcTanggalLelang.value)
  const now = new Date('2026-09-13')
  const diff = Math.round((target.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
  return diff >= 0 ? `${diff} Hari Menuju Pelaksanaan` : 'Jadwal Telah Lewat'
})

// Lifecycle states
const stateDefault = ref('')
const statePreselected = ref('2026-09-25')
const stateDisabled = ref('2026-08-01')
const stateError = ref('')

// Props Matrix Documentation
const datePickerProps = [
  {
    name: 'modelValue',
    type: 'String',
    default: 'null',
    description: 'Nilai tanggal yang terpilih (two-way binding via v-model).'
  },
  {
    name: 'title',
    type: 'String',
    default: "'Tanggal Lahir'",
    description: 'Label judul yang ditampilkan di atas kolom isian tanggal.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "''",
    description: 'Teks instruksi panduan placeholder sebelum tanggal ditentukan.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi pada date picker dan meredam visual komponen.'
  },
  {
    name: 'error',
    type: 'String',
    default: "''",
    description: 'Pesan validasi kesalahan yang muncul di bawah input dan mengaktifkan border merah.'
  }
]
</script>
