  { id: 1, label: '1. Pendaftaran Berkas', completed: true },
  { id: 2, label: '2. Taksiran Karat Emas', completed: false },
  { id: 3, label: '3. Otorisasi & Cetak SBG', completed: false }
])

// Varian 2 State (Accordion Mode)
const v2Labels = ref([
  { id: 101, label: 'Identitas Pribadi' },
  { id: 102, label: 'Kontak Darurat' },
  { id: 201, label: 'Uji Karatase Fisik' },
  { id: 202, label: 'Penetapan Nilai Wajar' }
])

const v2Accordions = ref([
  {
    header: 'Tahap 1: Data Nasabah',
    labels: [
      { id: 101, label: 'Identitas Pribadi', completed: true },
      { id: 102, label: 'Kontak Darurat', completed: false }
    ]
  },
  {
    header: 'Tahap 2: Penaksiran Marhun',
    labels: [
      { id: 201, label: 'Uji Karatase Fisik', completed: false },
      { id: 202, label: 'Penetapan Nilai Wajar', completed: false }
    ]
  }
])

// Real Case State
const rcLabels = ref([
  { id: 1, label: '1. Profil Nasabah & SLIK', completed: true },
  { id: 2, label: '2. Uji Marhun & Karatase', completed: true },
  { id: 3, label: '3. Otorisasi & Pencairan', completed: false }
])

const lastRcStatus = ref('Tahap 1 & 2 selesai diverifikasi, menunggu otorisasi kasir')

const markStepComplete = (stepId) => {
  const item = rcLabels.value.find(l => l.id === stepId)
  if (item) {
    item.completed = true
    lastRcStatus.value = `Langkah ${stepId} ditandai selesai diverifikasi`
  }
}

const simpanDraf = () => {
  alert('Draf transaksi penaksiran berhasil disimpan ke antrean kasir UPK.')
}

const kirimOtorisasi = () => {
  const item = rcLabels.value.find(l => l.id === 3)
  if (item) item.completed = true
  lastRcStatus.value = 'Seluruh tahapan taksiran tuntas dan SBG siap dicetak'
  alert('Otorisasi berhasil disetujui. Surat Bukti Gadai siap dicetak!')
}

function resetRcStep() {
  rcLabels.value.forEach((l, idx) => {
    l.completed = idx === 0
  })
  lastRcStatus.value = 'Data pemeriksaan direset kembali ke Tahap 1'
}

function loadRcStep() {
  rcLabels.value.forEach(l => {
    l.completed = true
  })
  lastRcStatus.value = 'Seluruh tahapan verifikasi berhasil ditandai selesai'
}

const sideStepperProps = [
  {
    name: 'title',
    type: 'String',
    default: "'Langkah'",
    description: 'Teks tajuk menu langkah di bagian atas panel navigasi samping.'
  },
  {
    name: 'labels',
    type: 'Array<Object>',
    default: 'Wajib (Required)',
    description: 'Daftar butir langkah dengan skema { id: Number|String, label: String, completed?: Boolean }.'
  },
  {
    name: 'variant',
    type: "'satu' | 'dua'",
    default: "'satu'",
    description: "Format tampilan: 'satu' untuk daftar tombol vertikal datar, atau 'dua' untuk pengelompokan menu akordion."
  },
  {
    name: 'accordions',
    type: 'Array<Object>',
    default: 'Preset 2 Grup',
    description: "Struktur data grup akordion saat variant='dua', berformat [{ header: String, labels: Array }]."
  },
  {
    name: '#[label.id]',
    type: 'Slot Konten Dinamis',
    default: '-',
    description: 'Slot kartu konten yang ditampilkan di panel sebelah kanan sesuai langkah yang sedang aktif.'
  }
]
</script>

