      .group-input {
        padding-left: 1.5rem;
        padding-right: 1.5rem;
      }
    }

    // 1 baris di atas & bawah - font-weight 600, mengecil
    &.dist-1 {
      font-size: 1.25rem;
      font-weight: 600;
