<script setup>
import { ref } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import ButtonSize from '@/components/Button/ButtonSize.vue'
import Button from '@/components/Button/Button.vue'
import Badge from '@/components/Badge/Badge.vue'

const activePreset = ref('all')
const lastLoggedAction = ref('Siap menjalankan aksi loket')

const defaultTransactions = [
  { sbg: 'SBG-2026-JKT-101', nasabah: 'Bambang Hariyanto', nominal: 'Rp 12.500.000,-', status: 'Menunggu Otorisasi', badgeType: 'secondary' },
  { sbg: 'SBG-2026-JKT-102', nasabah: 'Dewi Anggraeni', nominal: 'Rp 8.200.000,-', status: 'Menunggu Otorisasi', badgeType: 'secondary' },
  { sbg: 'SBG-2026-JKT-103', nasabah: 'Hendra Pratama', nominal: 'Rp 25.000.000,-', status: 'Terverifikasi', badgeType: 'primary' },
  { sbg: 'SBG-2026-JKT-104', nasabah: 'Siti Nurhaliza', nominal: 'Rp 4.500.000,-', status: 'Menunggu Otorisasi', badgeType: 'secondary' }
]

const kasirTransactions = ref([...defaultTransactions])

function applyPreset(preset) {
  activePreset.value = preset
  if (preset === 'table') {
    lastLoggedAction.value = 'Menyorot rekomendasi baris tabel (sm: 24px)'
  } else if (preset === 'form') {
    lastLoggedAction.value = 'Menyorot rekomendasi dialog formulir (md: 40px)'
  } else if (preset === 'cta') {
    lastLoggedAction.value = 'Menyorot rekomendasi tombol CTA utama (lg: 48px / xl: 52px)'
  } else {
    lastLoggedAction.value = 'Menampilkan seluruh matriks ukuran tombol'
  }
}

function handleAction(actionName, target) {
  lastLoggedAction.value = `Aksi '${actionName}' pada ${target} berhasil dipicu.`
}

function resetScenarioData() {
  applyPreset('table')
  kasirTransactions.value = defaultTransactions.slice(0, 2)
  lastLoggedAction.value = 'Data antrean loket direset ke 2 antrean utama.'
}

function loadScenarioData() {
  applyPreset('all')
  kasirTransactions.value = [...defaultTransactions]
  lastLoggedAction.value = 'Seluruh 4 antrean kasir loket berhasil dimuat ulang.'
}

const buttonSizeProps = [
  {
    name: 'class',
    type: 'String',
    default: "''",
    description: 'Kelas CSS kustom tambahan untuk wadah pembungkus trio tombol preset.'
  },
  {
    name: 'style',
    type: 'String | Object',
    default: "''",
    description: 'Atribut inline style untuk penyesuaian posisi wadah.'
  }
]
</script>

