<template>
  <nav class="pg-topnav position-sticky" role="tablist" aria-label="Navigasi Kategori Komponen">
    <!-- Edge Fade Masks (Overlaid on left and right) -->
    <div class="pg-topnav__fade pg-topnav__fade--left" aria-hidden="true"></div>
    <div class="pg-topnav__fade pg-topnav__fade--right" aria-hidden="true"></div>

    <!-- Scroll Chevron Buttons (Revealed on hover) -->
    <button
      type="button"
      class="pg-topnav__scroll-btn pg-topnav__scroll-btn--left"
      title="Scroll ke kiri"
      aria-label="Scroll navigation left"
      @click="scrollNav(-1)"
    >
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <polyline points="15 18 9 12 15 6"></polyline>
      </svg>
    </button>

    <div class="container pg-topnav__container">
      <div
        ref="navContainerRef"
        class="pg-topnav__track"
      >
        <button
          v-for="cat in categories"
          :key="cat.id"
          :id="`topnav-pill-${cat.id}`"
          :data-nav-id="cat.id"
          type="button"
          role="tab"
          :aria-selected="activeCategoryId === cat.id"
          class="pg-topnav__pill"
          :class="{ 'pg-topnav__pill--active': activeCategoryId === cat.id }"
          @click="emit('navigate', cat.id)"
        >
          <span
            v-if="activeCategoryId === cat.id"
            class="pg-topnav__dot"
            aria-hidden="true"
          ></span>
          <span class="pg-topnav__label">{{ cat.shortName }}</span>
          <span class="pg-topnav__count">{{ cat.components.length }}</span>
        </button>
      </div>
    </div>

    <button
      type="button"
      class="pg-topnav__scroll-btn pg-topnav__scroll-btn--right"
      title="Scroll ke kanan"
      aria-label="Scroll navigation right"
      @click="scrollNav(1)"
    >
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <polyline points="9 18 15 12 9 6"></polyline>
      </svg>
    </button>
  </nav>
</template>

<script setup>
/**
 * @file PlaygroundTopNav.vue
 * @description Segmented category top navigation bar with horizontal smooth scroll,
 * edge fade masks, hover reveal scroll chevron controls, and active indicator dot.
 */
import { ref } from 'vue'

defineProps({
  categories: {
    type: Array,
    default: () => []
  },
  activeCategoryId: {
    type: String,
    default: 'category-1'
  }
})

const emit = defineEmits(['navigate'])

const navContainerRef = ref(null)

function scrollNavPillIntoView(id) {
  if (!navContainerRef.value) return
  const pillEl = navContainerRef.value.querySelector(`[data-nav-id="${id}"]`)
  if (pillEl) {
    pillEl.scrollIntoView({
      behavior: 'smooth',
      inline: 'center',
      block: 'nearest'
    })
  }
}

function scrollNav(direction) {
  if (navContainerRef.value) {
    navContainerRef.value.scrollBy({
      left: direction * 260,
      behavior: 'smooth'
    })
  }
}

defineExpose({
  scrollNavPillIntoView
})
</script>

