const currentCase = ref({ ...invoicePresets.sewa })

function applyPreset(presetKey) {
  activePreset.value = presetKey
  currentCase.value = { ...invoicePresets[presetKey] }
  selectedPaymentChannel.value = 'Kas Tunai Loket UPK'
  auditLogText.value = `Tagihan ${currentCase.value.sbgNumber} dimuat.`
}

function resetScenarioData() {
  activePreset.value = 'sewa'
  currentCase.value = { ...invoicePresets.sewa }
  selectedPaymentChannel.value = 'Kas Tunai Loket UPK'
  auditLogText.value = 'Skenario di-reset ke status awal loket.'
}

function loadScenarioData() {
  applyPreset('tebus')
  auditLogText.value = 'Data pelunasan tebus agunan Rp 5.200.000 siap dipilih metode pembayarannya.'
}

function selectChannel(channel) {
  selectedPaymentChannel.value = channel
}

function confirmChannelSelection() {
  auditLogText.value = `Saluran ${selectedPaymentChannel.value} telah dikonfirmasi untuk pembayaran ${currentCase.value.sbgNumber}.`
  showRealCaseSheet.value = false
}

