<script setup>
import { ref, reactive } from 'vue'
import NewInputCamera from '@/components/Input/NewInputCamera.vue'
import Button from '@/components/Button/Button.vue'
import DocCard from '../components/DocCard.vue'
import PropsTable from '../components/PropsTable.vue'
import PlaygroundAlert from '../components/PlaygroundAlert.vue'

// Sampel Dummy Image Base64 Emas
const sampleEmasSvg = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="300" height="200" viewBox="0 0 300 200"><rect width="300" height="200" fill="%23fff8e1" rx="8"/><rect x="40" y="35" width="220" height="110" fill="%23ffd54f" stroke="%23ffb300" stroke-width="4" rx="6"/><text x="150" y="95" font-family="sans-serif" font-size="16" fill="%23e65100" text-anchor="middle" font-weight="bold">FINE GOLD 999.9</text><text x="150" y="125" font-family="sans-serif" font-size="12" fill="%23f57f17" text-anchor="middle">25 GRAMS • ANTAM</text></svg>'

// Koordinat Dummy Kantor Cabang Pegadaian (Kramat Raya Jakarta Pusat)
const cabangCoordinate = {
  lat: -6.1856,
  lng: 106.8456
}

// State Varian (6 Varian Lengkap)
const v1PhotoWatermark = ref('')
const v2PhotoLiveOnly = ref('')
const v3PhotoNote = ref('')
const v4PhotoConfirm = ref('')
const v5PhotoMobile = ref('')
const v6PhotoExisting = ref(sampleEmasSvg)

const resetV6Sample = () => {
  v6PhotoExisting.value = sampleEmasSvg
}

// State Real Case
const activePreset = ref('empty')
const rcPhotoAgunan = ref('')
const rcItemData = reactive({
  nama: '',
  berat: '',
  hps: '-'
})

const applyPreset = (mode) => {
  activePreset.value = mode
  if (mode === 'antam') {
    rcPhotoAgunan.value = sampleEmasSvg
    rcItemData.nama = 'Logam Mulia Antam CertiCard'
    rcItemData.berat = '25.00 Gram (Karatase 24K)'
    rcItemData.hps = 'Rp 29.625.000'
  } else if (mode === 'perhiasan') {
    rcPhotoAgunan.value = sampleEmasSvg
    rcItemData.nama = 'Kalung Rantai Emas Kuning'
    rcItemData.berat = '15.40 Gram (Karatase 22K)'
    rcItemData.hps = 'Rp 14.168.000'
  } else {
    resetAgunanRealCase()
  }
}

const loadSampleAgunan = () => {
  applyPreset('antam')
}

const handleAgunanDropped = () => {
  if (!rcItemData.nama) {
    rcItemData.nama = 'Logam Mulia Antam CertiCard'
    rcItemData.berat = '25.00 Gram (Karatase 24K)'
    rcItemData.hps = 'Rp 29.625.000'
    activePreset.value = 'antam'
  }
}

const resetAgunanRealCase = () => {
  activePreset.value = 'empty'
  rcPhotoAgunan.value = ''
  rcItemData.nama = ''
  rcItemData.berat = ''
  rcItemData.hps = '-'
}

const lanjutCetakSbg = () => {
  alert('Foto agunan emas terverifikasi dan stempel GPS audit terekam! Lanjut ke proses cetak SBG kasir.')
}

// Props Matrix Documentation
const newInputCameraProps = [
  {
    name: 'userName',
    type: 'String',
    default: 'Wajib (Required)',
    description: 'Nama user / petugas yang melakukan perekaman foto untuk dibubuhkan pada stempel watermark audit.'
  },
  {
    name: 'v-model',
    type: 'String (DataURL / URL)',
    default: 'undefined',
    description: 'Model data berkas gambar hasil jepretan kamera ter-watermark yang terikat dua arah.'
  },
  {
    name: 'useWatermark',
    type: 'Boolean',
    default: 'false',
    description: 'Mengaktifkan pembubuhan stempel watermark nama petugas, tanggal-jam, dan koordinat GPS pada foto.'
  },
  {
    name: 'deviceCoordinate',
    type: 'Object { lat, lng }',
    default: 'null',
    description: 'Objek koordinat GPS perangkat untuk keperluan audit jejak lokasi penaksiran agunan lapangan.'
  },
  {
    name: 'disableOptions',
    type: 'String',
    default: "''",
    description: "Opsi sumber yang dinonaktifkan. Isi 'gallery' untuk memaksa perekaman langsung via kamera live saja."
  },
  {
    name: 'noteText',
    type: 'String',
    default: "''",
    description: 'Pesan catatan instruksi tambahan yang ditampilkan di bagian bawah dialog modal kamera.'
  },
  {
    name: 'showPreviewConfirmButton',
    type: 'Boolean',
    default: 'false',
    description: 'Menampilkan tombol konfirmasi simpan foto pada modal pratinjau hasil tangkapan kamera.'
  },
  {
    name: 'useBottomSheet',
    type: 'Boolean',
    default: 'false',
    description: 'Menampilkan dialog modal sebagai BottomSheet ramah mobile saat diakses pada layar smartphone.'
  },
  {
    name: '@fileDropped',
    type: 'Event (File, uniqueKey)',
    default: '-',
    description: 'Dipancarkan setelah berkas foto berhasil diambil dan selesai dibubuhi stempel watermark.'
  }
]
</script>

