<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import CustomCheckbox from '@/components/Checkbox/CustomCheckbox.vue'

// Real-world scenario state
const docKtp = ref(true)
const docNpwp = ref(true)
const docNib = ref(false)
const docRekening = ref(false)

const totalScore = computed(() => {
  let score = 0
  if (docKtp.value) score += 35
  if (docNpwp.value) score += 20
  if (docNib.value) score += 25
  if (docRekening.value) score += 20
  return score
})

const completedDocsCount = computed(() => {
  return [docKtp.value, docNpwp.value, docNib.value, docRekening.value].filter(Boolean).length
})

const isAllCompleted = computed(() => totalScore.value === 100)

const complianceStatus = computed(() => {
  if (totalScore.value >= 80) return 'Lolos Verifikasi'
  if (totalScore.value >= 60) return 'Perlu Konfirmasi'
  return 'Berkas Kurang'
})

const complianceBadgeClass = computed(() => {
  if (totalScore.value >= 80) return 'bg-success-subtle text-success border-success-subtle'
  if (totalScore.value >= 60) return 'bg-warning-subtle text-warning border-warning-subtle'
  return 'bg-danger-subtle text-danger border-danger-subtle'
})

const slaDuration = computed(() => {
  if (totalScore.value >= 80) return '15 Menit (Fast-Track)'
  if (totalScore.value >= 60) return '2 Jam (Verifikasi Analis)'
  return 'Menunggu Kelengkapan'
})

const riskProfile = computed(() => {
  if (totalScore.value >= 80) return 'Sangat Rendah (A)'
  if (totalScore.value >= 60) return 'Moderat (B)'
  return 'Tinggi (C)'
})

const committeeDecision = computed(() => {
  if (totalScore.value >= 80) return 'Rekomendasi Setuju'
  if (totalScore.value >= 60) return 'Butuh Agunan Tambahan'
  return 'Tolak Otomatis'
})

const activePreset = ref('standard')

function applyPreset(preset) {
  activePreset.value = preset
  if (preset === 'full') {
    setDocsPreset(true, true, true, true)
  } else if (preset === 'standard') {
    setDocsPreset(true, false, true, false)
  } else if (preset === 'initial') {
    setDocsPreset(true, false, false, false)
  } else if (preset === 'empty') {
    setDocsPreset(false, false, false, false)
  }
}

function checkCustomPreset() {
  if (docKtp.value && docNpwp.value && docNib.value && docRekening.value) {
    activePreset.value = 'full'
  } else if (docKtp.value && !docNpwp.value && docNib.value && !docRekening.value) {
    activePreset.value = 'standard'
  } else if (docKtp.value && !docNpwp.value && !docNib.value && !docRekening.value) {
    activePreset.value = 'initial'
  } else if (!docKtp.value && !docNpwp.value && !docNib.value && !docRekening.value) {
    activePreset.value = 'empty'
  } else {
    activePreset.value = 'custom'
  }
}

function setDocsPreset(ktp, npwp, nib, rek) {
  docKtp.value = ktp
  docNpwp.value = npwp
  docNib.value = nib
  docRekening.value = rek
}

function resetScenarioData() {
  applyPreset('empty')
}

function loadScenarioData() {
  applyPreset('full')
}

// Lifecycle states
const stateUnchecked = ref(false)
const stateChecked = ref(true)
const stateSecondary = ref(true)
const stateDisabled = ref(true)

// Props Matrix Documentation
const checkboxProps = [
  {
    name: 'modelValue',
    type: 'Boolean',
    default: 'false',
    isModel: true,
    description: 'Status nilai centang aktif yang terikat secara two-way binding via v-model.'
  },
  {
    name: 'label',
    type: 'String',
    default: "''",
    description: 'Teks keterangan judul di samping kanan kotak centang.'
  },
  {
    name: 'color',
    type: "'primary' | 'secondary'",
    default: "'primary'",
    description: "Varian warna visual centang: 'primary' (hijau Pegadaian) atau 'secondary' (netral)."
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi klik pengguna dan memberi gaya visual muted redup.'
  },
  {
    name: 'checkboxTextClass',
    type: 'String',
    default: "'checkbox-text'",
    description: 'Kelas CSS kustom tambahan untuk elemen teks label.'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat status centang berubah, membawa nilai boolean terbaru.'
  }
]
</script>

