<script setup>
import { ref } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import ButtonLeftSlider from '@/components/Button/ButtonLeftSlider.vue'
import ButtonRightSlider from '@/components/Button/ButtonRightSlider.vue'
import Button from '@/components/Button/Button.vue'

const photos = [
  { title: 'Tampak Depan Logam Mulia 10 Gram', desc: 'Sertifikat Antam Cetakan 2024 tertera utuh tanpa cacat segel.' },
  { title: 'Cap Karatase & Berat Presisi', desc: 'Uji karatase 99.99% terkonfirmasi melalui alat uji karatase elektronik.' },
  { title: 'Sertifikat Resmi LBMA', desc: 'Nomor seri SBG-EMAS-0922 cocok dengan database pusat Antam.' }
]

const activeIndex = ref(0)

function prevPhoto() {
  activeIndex.value = (activeIndex.value - 1 + photos.length) % photos.length
}

function nextPhoto() {
  activeIndex.value = (activeIndex.value + 1) % photos.length
}

function handleDemoClick(direction) {
  if (direction === 'Kiri') prevPhoto()
  else nextPhoto()
}

function resetScenarioData() {
  activeIndex.value = 0
}

function loadScenarioData() {
  activeIndex.value = 1
}

const sliderProps = [
  {
    name: '@click',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat pengguna mengklik tombol arah slider.'
  },
  {
    name: 'class',
    type: 'String',
    default: "''",
    description: 'Penyematan kelas CSS kustom untuk penyesuaian posisi relatif wadah slider.'
  },
  {
    name: 'style',
    type: 'String | Object',
    default: "''",
    description: 'Penyematan inline style untuk koordinat letak (left, right, top).'
  }
]
</script>
