        label: 'Biaya Pendidikan & Keluarga (Konsumtif)',
        backgroundColor: '#fdb913',
        data: [16, 14, 18, 15, 12]
      }
    ]
  } else {
    return [
      {
        label: 'Modal Kerja UMKM (Produktif)',
        backgroundColor: '#00883e',
        data: [22, 26, 20]
      },
      {
        label: 'Investasi Usaha (Produktif)',
        backgroundColor: '#1e88e5',
        data: [10, 12, 8]
      },
      {
        label: 'Biaya Pendidikan & Keluarga (Konsumtif)',
        backgroundColor: '#fdb913',
        data: [16, 14, 18]
      }
    ]
  }
})

function resetScenarioData() {
  isAllBranches.value = false
  lastScenarioStatus.value = 'Data difokuskan ke 3 Cabang teratas (Kramat, Senen, Cikini)'
}

function loadScenarioData() {
  isAllBranches.value = true
  lastScenarioStatus.value = 'Seluruh 5 Cabang Utama berhasil dimuat ulang'
}

