    name: 'showLegend',
    type: 'Boolean',
    default: 'true',
    description: 'Mengontrol apakah bilah legenda kategori ditampilkan di bagian atas grafik.'
  },
  {
    name: 'options',
    type: 'Object',
    default: '{}',
    description: 'Opsi Chart.js untuk kustomisasi skala dan perilaku grafik.'
  },
  {
    name: 'class',
    type: 'String',
    default: "''",
    description: 'Kelas CSS pembungkus luar (wrapper) komponen grafik.'
  },
  {
    name: '#tooltip',
