<template>
  <div :class="{ 'variant': variant === 'aksen' || variant === 'pastel' }">
    <div :class="`alert alert-${color} ${variantClass}`">
      <div class="row">
        <div :class="{ 'col-10' : !hideAction }">
          {{ label }}
        </div>
        <div class="col-2 text-end" v-if="!hideAction">
          <slot name="action" />
        </div>
      </div>
    </div>
  </div>
</template>

<script>
  export default {
    name: "AlertVarian",
    props: {
      label: String,
      color: {
        validator(value) {
          return ["green", "light-blue", "red", "yellow", "success", "info", "warning", "danger", "link"].includes(value);
        },
      },
      variant: String,
      hideAction: {
        type: Boolean,
        default: true
      }
    },
    computed: {
      variantClass() {
        if (this.variant === 'aksen' || this.variant === 'pastel') {
          const colorMap = {
            green: 'success',
            'light-blue': 'info',
            yellow: 'warning',
            red: 'danger',
            success: 'success',
            info: 'info',
            warning: 'warning',
            danger: 'danger'
          };
          return `alert-${colorMap[this.color] || this.color}`;
        }
        return this.variant ? `alert-${this.variant}` : '';
      },
    },
  };
</script>