<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputNominalStart from '@/components/Input/InputNominalStart.vue'

// Real-world scenario state
const rcTaksiran = ref('20000000')
const rcPinjaman = ref('17000000')

function resetScenarioData() {
  rcTaksiran.value = ''
  rcPinjaman.value = ''
}

function loadScenarioData() {
  rcTaksiran.value = '35000000'
  rcPinjaman.value = '29750000'
}

function setPreset(taksiran, pinjaman) {
  rcTaksiran.value = taksiran
  rcPinjaman.value = pinjaman
}

function formatRupiah(val) {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    maximumFractionDigits: 0
  }).format(val || 0)
}

// Computed Loan Calculation Engine
const loanCalculation = computed(() => {
  const taksiran = Number(rcTaksiran.value) || 0
  const pinjaman = Number(rcPinjaman.value) || 0

  if (taksiran === 0 || pinjaman === 0) {
    return {
      ltv: 0,
      isLtvSafe: true,
      golongan: 'Menunggu Input',
      biayaAdmin: 0,
      tarifSewaModal: 1.15,
      sewaModal15Hari: 0,
      uangBersih: 0,
      approvalStatus: 'Draft Pengajuan',
      approvalBadgeClass: 'bg-secondary-subtle text-secondary border-secondary-subtle',
      message: 'Masukkan taksiran agunan & nominal pinjaman untuk kalkulasi'
    }
  }

  const ltv = parseFloat(((pinjaman / taksiran) * 100).toFixed(1))
  const isLtvSafe = ltv <= 85

  // Determine Golongan Pinjaman Pegadaian
  let golongan = 'Golongan D (> Rp 20 Jt)'
  let biayaAdmin = 125000
  let tarifSewaModal = 1.15

  if (pinjaman <= 500000) {
    golongan = 'Golongan A (s.d Rp 500 Ribu)'
    biayaAdmin = 2000
    tarifSewaModal = 0.75
  } else if (pinjaman <= 5000000) {
    golongan = 'Golongan B (Rp 500 Rb - Rp 5 Jt)'
    biayaAdmin = 20000
    tarifSewaModal = 1.15
  } else if (pinjaman <= 20000000) {
    golongan = 'Golongan C (Rp 5 Jt - Rp 20 Jt)'
    biayaAdmin = 50000
    tarifSewaModal = 1.15
  }

  const sewaModal15Hari = Math.round(pinjaman * (tarifSewaModal / 100))
  const uangBersih = Math.max(0, pinjaman - biayaAdmin)

  let approvalStatus = 'Disetujui Penaksir Loket'
  let approvalBadgeClass = 'bg-success-subtle text-success border-success-subtle'

  if (!isLtvSafe) {
    approvalStatus = 'Ditolak: LTV Melebihi 85%'
    approvalBadgeClass = 'bg-danger-subtle text-danger border-danger-subtle'
  } else if (pinjaman > 50000000) {
    approvalStatus = 'Memerlukan Otorisasi Komite Wilayah'
    approvalBadgeClass = 'bg-primary-subtle text-primary border-primary-subtle'
  }

  return {
    ltv,
    isLtvSafe,
    golongan,
    biayaAdmin,
    tarifSewaModal,
    sewaModal15Hari,
    uangBersih,
    approvalStatus,
    approvalBadgeClass,
    message: isLtvSafe
      ? 'Plafon pinjaman memenuhi rasio batas aman kredit gadai'
      : 'Plafon pinjaman melampaui batas toleransi 85% taksiran agunan'
  }
})

// Lifecycle states
const stateDefault = ref('')
const stateRp = ref('')
const stateFilled = ref('25000000')
const stateDisabled = ref('50000000')

// Props Matrix Documentation
const nominalStartProps = [
  {
    name: 'modelValue',
    type: 'String | Number',
    default: "''",
    description: 'Nilai numerik mentah tanpa tanda titik yang diikat secara two-way binding via v-model.'
  },
  {
    name: 'unit',
    type: 'String',
    default: "'Rupiah'",
    description: "Label teks satuan prefix di sisi kiri (misal: 'Rp', 'Rupiah', 'IDR')."
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "'Masukkan rupiah'",
    description: 'Teks petunjuk ketika kolom nominal masih kosong.'
  },
  {
    name: 'class',
    type: 'String',
    default: "''",
    description: 'Kelas CSS kustom tambahan untuk kontainer input.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi pada kolom input.'
  },
  {
    name: '#prefix',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot ornamen/label prefix di sisi kiri input jika ingin kustomisasi oltre unit bawaan.'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat nominal berubah, menghasilkan angka murni unformatted.'
  }
]
</script>
