<!-- eslint-disable vue/multi-word-component-names -->
<template>
  <div class="aspect-container" :style="containerStyle">
    <div class="aspect-inner">
      <slot>
        <div class="aspect-default-content">
          This will always be an aspect of "{{ aspect }}",
          except when the content is too tall.
        </div>
      </slot>
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue'

defineOptions({
  name: 'AspectRatio'
})

const props = defineProps({
  aspect: {
    type: [String, Number],
    default: '16:9'
  }
})

const computedRatio = computed(() => {
  if (typeof props.aspect === 'number') {
    return String(props.aspect)
  }
  const str = String(props.aspect || '16:9').trim()
  if (str.includes(':')) {
    const [w, h] = str.split(':')
    return `${w} / ${h}`
  }
  return str
})

const containerStyle = computed(() => ({
  aspectRatio: computedRatio.value,
  position: 'relative',
  width: '100%'
}))
</script>

<style scoped>
.aspect-container {
  display: block;
  width: 100%;
  position: relative;
}

.aspect-inner {
  width: 100%;
  height: 100%;
}

.aspect-default-content {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f8fafc;
  color: #64748b;
  padding: 1rem;
  text-align: center;
}
</style>