<script setup>
defineOptions({
  name: 'SwitchComponentSection'
})
import { ref, computed } from 'vue'
import SwitchComponent from '@/components/Switch/Switch.vue'
import Button from '@/components/Button/Button.vue'
import DocCard from '../components/DocCard.vue'
import PropsTable from '../components/PropsTable.vue'

// Card 1: Scenario Data
const scenarioAutoRollOver = ref(true)
const scenarioWaReminder = ref(true)
const scenarioVaultAuth = ref(true)

const activeLayananCount = computed(() => {
  return [scenarioAutoRollOver.value, scenarioWaReminder.value, scenarioVaultAuth.value].filter(Boolean).length
})

const securityLevel = computed(() => {
  if (scenarioVaultAuth.value && scenarioAutoRollOver.value && scenarioWaReminder.value) return 'Grade A+ (Maksimal)'
  if (scenarioVaultAuth.value) return 'Grade A (Aman)'
  if (scenarioAutoRollOver.value || scenarioWaReminder.value) return 'Grade B (Standar)'
  return 'Grade C (Minimal)'
})

const securityBadgeClass = computed(() => {
  if (activeLayananCount.value === 3) return 'bg-success-subtle text-success border-success-subtle'
  if (activeLayananCount.value >= 1) return 'bg-primary-subtle text-primary border-primary-subtle'
  return 'bg-warning-subtle text-warning border-warning-subtle'
})

const riskAssessment = computed(() => {
  if (scenarioVaultAuth.value) return 'Terkendali & Terpantau'
  return 'Perlu Supervisi Loket'
})

function setSwitchPreset(roll, wa, vault) {
  scenarioAutoRollOver.value = roll
  scenarioWaReminder.value = wa
  scenarioVaultAuth.value = vault
}

function resetScenarioData() {
  setSwitchPreset(false, false, false)
}

function loadScenarioData() {
  setSwitchPreset(true, true, true)
}

// Card 2: Lifecycle States
const tileSwitchOff = ref(false)
const tileSwitchOn = ref(true)
const tileSwitchKb = ref(true)
const tileSwitchSync = ref(false)

// Card 3: Props Matrix Documentation
const switchProps = [
  {
    name: 'modelValue',
    type: 'Boolean',
    default: 'false',
    isModel: true,
    description: 'Nilai status biner sakelar toggle (aktif: true / nonaktif: false) melalui two-way binding v-model.'
  },
  {
    name: 'id',
    type: 'String',
    default: "'switch'",
    description: 'ID unik atribut elemen input checkbox native untuk keterkaitan elemen label dan aksesibilitas for.'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat status sakelar berubah akibat klik kursor mouse atau tekanan tombol Enter keyboard.'
  }
]
</script>

