<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputSmallText from '@/components/Input/InputSmallText.vue'
import searchIcon from '@/assets/icon/search.svg'
import infoIcon from '@/assets/icon/info.svg'
import lockIcon from '@/assets/icon/lock.svg'

// Real-world scenario state
const rcUpk = ref('UPK-SALEMBA-01')
const rcNip = ref('PGD-991204')
const rcPin = ref('123456')

function resetScenarioData() {
  rcUpk.value = ''
  rcNip.value = ''
  rcPin.value = ''
}

function loadScenarioData() {
  rcUpk.value = 'UPK-KRAMAT-02'
  rcNip.value = 'PGD-774012'
  rcPin.value = '987654'
}

function setPreset(upk, nip, pin) {
  rcUpk.value = upk
  rcNip.value = nip
  rcPin.value = pin
}

// Session Key & Dual-Control Engine
const sessionInfo = computed(() => {
  const upk = String(rcUpk.value || '').trim()
  const nip = String(rcNip.value || '').trim()
  const pin = String(rcPin.value || '').trim()

  if (!upk || !nip || !pin) {
    return {
      isValid: false,
      statusBadge: 'Menunggu Kredensial',
      sessionToken: 'SES-PENDING-AUTH',
      plafonWewenang: 'Rp 0',
      jabatan: 'Menunggu Input',
      message: 'Masukkan kode UPK, NIP, dan PIN otorisasi loket'
    }
  }

  const tokenSuffix = (nip.replace(/\D/g, '') || '88').slice(-3)
  return {
    isValid: true,
    statusBadge: 'Sesi Kasir Terotorisasi',
    sessionToken: `SES-2026-X${tokenSuffix}-PGD`,
    plafonWewenang: 'Maks. Rp 50.000.000 (Mandiri)',
    jabatan: 'Penaksir Madya Kelas II',
    message: 'Kunci sesi loket aktif, wewenang pencairan pinjaman siap digunakan'
  }
})

// Lifecycle states
const nipValue = ref('')
const upkValue = ref('')
const pinValue = ref('')

// Props Matrix Documentation
const smallTextProps = [
  {
    name: 'value',
    type: 'String',
    default: "''",
    isModel: true,
    description: 'Nilai masukan teks yang terhubung secara two-way binding (:value atau v-model).'
  },
  {
    name: 'title',
    type: 'String',
    default: 'null',
    description: 'Teks judul label di atas kolom input.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "'placeholder . . .'",
    description: 'Teks petunjuk ketika kolom masukan kosong.'
  },
  {
    name: 'icon',
    type: 'String',
    default: 'null',
    description: 'URL atau path aset gambar ikon di dalam kolom input (sisi kiri).'
  },
  {
    name: 'iconLabel',
    type: 'String',
    default: 'null',
    description: 'URL atau path gambar ikon penjelas tepat di samping teks label.'
  },
  {
    name: 'iconRight',
    type: 'String',
    default: 'null',
    description: 'URL atau path gambar ikon di sisi kanan kolom input.'
  },
  {
    name: 'type',
    type: 'String',
    default: "'text'",
    description: 'Tipe HTML input standar (text, password, number).'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi pada kolom input.'
  },
  {
    name: 'required',
    type: 'Boolean',
    default: 'false',
    description: 'Menandai kolom wajib diisi dan memicu pesan error otomatis jika kosong.'
  },
  {
    name: 'error',
    type: 'Boolean',
    default: 'false',
    description: 'Status kesalahan validasi yang mengaktifkan styling outline error merah.'
  },
  {
    name: 'errorMessage',
    type: 'String',
    default: "''",
    description: 'Pesan kesalahan kustom di bawah kolom input saat validasi gagal.'
  },
  {
    name: 'id',
    type: 'String',
    default: "'inputField'",
    description: 'Identifier unik elemen untuk relasi label dan pembaca layar.'
  },
  {
    name: '@input',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Event yang dipancarkan saat pengguna mengetik, membawa nilai teks masukan terbaru.'
  }
]
</script>
