<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import DoughnutChart from '@/components/Chart/DoughnutChart.vue'
import Button from '@/components/Button/Button.vue'
import Alert from '@/components/Alert/AlertVarian.vue'

// --- Skenario Riil Interaktif ---
const isAllProfessions = ref(true)
const lastScenarioStatus = ref('Menampilkan 5 segmen demografi profesi nasabah cabang')

const fullLabels = ['Pedagang & UMKM', 'Karyawan Swasta', 'Pegawai Negeri/BUMN', 'Ibu Rumah Tangga', 'Profesional/Lainnya']
const fullValues = [42, 26, 14, 12, 6]
const fullColors = ['#00883e', '#1e88e5', '#fdb913', '#e53935', '#757575']
const fullCifs = ['5.229 CIF', '3.237 CIF', '1.743 CIF', '1.494 CIF', '747 CIF']

const scenarioLabels = computed(() =>
  isAllProfessions.value ? fullLabels : fullLabels.slice(0, 3)
)

const scenarioValues = computed(() =>
  isAllProfessions.value ? fullValues : fullValues.slice(0, 3)
)

const scenarioColors = computed(() =>
  isAllProfessions.value ? fullColors : fullColors.slice(0, 3)
)

const scenarioBreakdown = computed(() => {
  const count = isAllProfessions.value ? 5 : 3
  const items = []
  for (let i = 0; i < count; i++) {
    items.push({
      label: fullLabels[i],
      percent: fullValues[i],
      cif: fullCifs[i],
      color: fullColors[i]
    })
  }
  return items
})

function resetScenarioData() {
  isAllProfessions.value = false
  lastScenarioStatus.value = 'Data difokuskan ke 3 profesi mayoritas debitur'
}

function loadScenarioData() {
  isAllProfessions.value = true
  lastScenarioStatus.value = 'Seluruh 5 segmen demografi profesi berhasil dimuat ulang'
}

// Options
const legendRightOptions = {
  responsive: true,
  maintainAspectRatio: false,
  layout: {
    padding: 14
  },
  plugins: {
    legend: {
      position: 'right',
      labels: { boxWidth: 12, padding: 16, font: { size: 11 } }
    }
  }
}

const legendBottomOptions = {
  responsive: true,
  maintainAspectRatio: false,
  layout: {
    padding: {
      top: 12,
      bottom: 8,
      left: 10,
      right: 10
    }
  },
  plugins: {
    legend: {
      position: 'bottom',
      labels: { boxWidth: 12, padding: 10, font: { size: 11 } }
    }
  }
}

const interactiveDoughnutOptions = {
  responsive: true,
  maintainAspectRatio: false,
  layout: {
    padding: 14
  },
  plugins: {
    legend: {
      position: 'right',
      labels: { boxWidth: 12, padding: 16, font: { size: 11 } }
    }
  }
}

const realCaseDoughnutOptions = {
  responsive: true,
  maintainAspectRatio: false,
  layout: {
    padding: 14
  },
  plugins: {
    legend: { display: false }
  }
}

const doughnutProps = [
  {
    name: 'labels',
    type: 'Array<String>',
    default: '[]',
    description: 'Daftar nama segmen data (misalnya jenis agunan jaminan atau kategori profesi nasabah).'
  },
  {
    name: 'values',
    type: 'Array<Number>',
    default: '[]',
    description: 'Prop Utama: Array angka kuantitatif nilai masing-masing segmen (misalnya persentase atau nominal).'
  },
  {
    name: 'colors',
    type: 'Array<String>',
    default: '[] (default 6 warna)',
    description: 'Array kode warna heksadesimal untuk masing-masing irisan busur donat secara berurutan.'
  },
  {
    name: 'options',
    type: 'Object',
    default: '{}',
    description: 'Objek konfigurasi override Chart.js (posisi legenda, cutout/lubang donat, layout padding).'
  },
  {
    name: 'class',
    type: 'String',
    default: "''",
    description: 'Kelas CSS tambahan pada kontainer pembungkus donat.'
  },
  {
    name: '#tooltip',
    type: 'Slot (Scoped)',
    default: 'Tooltip bawaan',
    description: 'Slot scoped untuk merender kartu HTML kustom saat kursor hover di atas irisan busur donat.'
  }
]
</script>

