<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputMonth from '@/components/Input/InputMonth.vue'

// Real-world scenario state
const rcPeriodeOSL = ref('2026-09')

function resetScenarioData() {
  rcPeriodeOSL.value = ''
}

function loadScenarioData() {
  rcPeriodeOSL.value = '2026-10'
}

const formattedPeriodLabel = computed(() => {
  if (!rcPeriodeOSL.value) return 'Belum ditentukan'
  const [y, m] = rcPeriodeOSL.value.split('-')
  const date = new Date(parseInt(y, 10), parseInt(m, 10) - 1, 1)
  return new Intl.DateTimeFormat('id-ID', { month: 'long', year: 'numeric' }).format(date)
})

const isCurrentMonth = computed(() => {
  return rcPeriodeOSL.value === '2026-09'
})

// Lifecycle states
const stateDefault = ref('')
const statePreselected = ref('2026-08')
const stateDisabled = ref('2025-12')
const stateTopPosition = ref('2026-09')

// Props Matrix Documentation
const inputMonthProps = [
  {
    name: 'modelValue',
    type: 'String',
    default: "''",
    description: 'Nilai bulan dan tahun yang terpilih (format: YYYY-MM), two-way data binding via v-model.'
  },
  {
    name: 'title',
    type: 'String',
    default: "'Tanggal Lahir'",
    description: 'Label judul yang ditampilkan di atas kolom input periode bulan.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "''",
    description: 'Teks instruksi placeholder sebelum pengguna memilih bulan dan tahun.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi pada pemilih bulan dan menerapkan visual teredam.'
  },
  {
    name: 'datePosition',
    type: 'String',
    default: "'bottom'",
    description: "Arah munculnya panel pop-up grid bulan ('top' atau 'bottom')."
  }
]
</script>
