<script setup>
import { ref, reactive, computed } from 'vue'
import FilePickerSM from '@/components/Filepicker/FilePickerSM.vue'
import Button from '@/components/Button/Button.vue'
import Badge from '@/components/Badge/Badge.vue'
import DocCard from '../components/DocCard.vue'
import PropsTable from '../components/PropsTable.vue'
import PlaygroundAlert from '../components/PlaygroundAlert.vue'
import sampleImages from '../fixtures/sample-images.js'

// State Real Case
const activePreset = ref('kalung')

const rcPhotos = reactive({
  front: sampleImages.goldJewelry,
  back: sampleImages.goldJewelry,
  hallmark: sampleImages.goldBar,
  invoice: sampleImages.certificateDoc
})

const applyPreset = (mode) => {
  activePreset.value = mode
  if (mode === 'kalung') {
    rcPhotos.front = sampleImages.goldJewelry
    rcPhotos.back = sampleImages.goldJewelry
    rcPhotos.hallmark = sampleImages.goldBar
    rcPhotos.invoice = sampleImages.certificateDoc
  } else if (mode === 'cincin') {
    rcPhotos.front = sampleImages.goldJewelry
    rcPhotos.back = sampleImages.goldJewelry
    rcPhotos.hallmark = sampleImages.goldBar
    rcPhotos.invoice = null
  } else {
    rcPhotos.front = null
    rcPhotos.back = null
    rcPhotos.hallmark = null
    rcPhotos.invoice = null
  }
}

const loadSampleJewelry = () => {
  applyPreset('kalung')
}

const resetRealCase = () => {
  applyPreset('empty')
}

const isAnyPhotoLoaded = computed(() => {
  return Boolean(rcPhotos.front || rcPhotos.back || rcPhotos.hallmark || rcPhotos.invoice)
})

const totalWajibTerisi = computed(() => {
  let count = 0
  if (rcPhotos.front) count++
  if (rcPhotos.back) count++
  if (rcPhotos.hallmark) count++
  return count
})

const verifikasiLoket = () => {
  alert('Seluruh sudut foto agunan telah diverifikasi dan siap dicetak pada formulir SBG!')
}

// Props Table Data
const filePickerSMProps = [
  {
    name: 'imageOnly',
    type: 'Boolean',
    default: 'false',
    description: 'Membuka modal pemilih Galeri & Kamera (Webcam) khusus format berkas gambar.'
  },
  {
    name: 'pdfOnly',
    type: 'Boolean',
    default: 'false',
    description: 'Membatasi unggahan hanya berkas dokumen PDF (.pdf).'
  },
  {
    name: 'csvOnly',
    type: 'Boolean',
    default: 'false',
    description: 'Membatasi unggahan hanya berkas tabel spreadsheet CSV (.csv).'
  },
  {
    name: 'file',
    type: 'String (URL)',
    default: "''",
    description: 'URL berkas atau gambar awal untuk langsung memunculkan thumbnail.'
  },
  {
    name: 'maxSize',
    type: 'Number',
    default: '1048576 (1MB)',
    description: 'Batas maksimum ukuran berkas yang diperbolehkan dalam satuan byte.'
  },
  {
    name: 'loaderType',
    type: "'modal' | 'inline'",
    default: "'modal'",
    description: 'Animasi indikator saat berkas sedang diunggah atau diproses.'
  },
  {
    name: 'errorText',
    type: 'String',
    default: "''",
    description: 'Pesan kesalahan validasi berkas ketika format tidak sesuai atau ukuran melebihi batas.'
  },
  {
    name: 'uniqueKey',
    type: 'String',
    default: "''",
    description: 'Identifier unik komponen untuk menghindari tabrakan ID input file pada DOM.'
  },
  {
    name: '@input',
    type: 'Event (File)',
    default: '-',
    description: 'Dipancarkan ketika berkas berhasil dipilih dari galeri atau diambil dari kamera.'
  },
  {
    name: '#footer',
    type: 'Scoped Slot ({ hide })',
    default: '-',
    description: 'Slot kustom tombol aksi pada modal pratinjau gambar.'
  }
]
</script>



