  activePreset.value = mode
  if (mode === 'emas') {
    rcLegalDoc.value = sampleImages.certificateDoc
    rcAgunanPhoto.value = sampleImages.goldBar
  } else if (mode === 'kendaraan') {
    rcLegalDoc.value = sampleImages.certificateDoc
    rcAgunanPhoto.value = sampleImages.branchBuilding
  } else {
    rcLegalDoc.value = null
    rcAgunanPhoto.value = null
  }
}

const loadSampleGadaiEmas = () => {
  applyPreset('emas')
}

const resetRealCase = () => {
  applyPreset('empty')
}

const simpanBerkas = () => {
  alert('Kelengkapan dokumen agunan nasabah berhasil diunggah ke repositori kredit Pegadaian!')
}

// Props Table Data
