  {
    name: 'imageOnly',
    type: 'Boolean',
    default: 'false',
    description: 'Membatasi hanya berkas format gambar (image/*) dan menampilkan pratinjau thumbnail.'
  },
  {
    name: 'pdfOnly',
    type: 'Boolean',
    default: 'false',
    description: 'Membatasi hanya dokumen format PDF (.pdf).'
  },
  {
    name: 'csvOnly',
    type: 'Boolean',
    default: 'false',
    description: 'Membatasi hanya dokumen spreadsheet CSV (.csv).'
  },
  {
    name: 'file',
    type: 'String (URL)',
    default: "''",
    description: 'Nilai pre-filled URL berkas atau gambar awal yang langsung memunculkan thumbnail.'
  },
  {
    name: 'maxSize',
    type: 'Number',
    default: '1048576 (1MB)',
    description: 'Ukuran maksimum berkas yang diperbolehkan dalam satuan byte.'
  },
  {
    name: 'loaderType',
    type: "'modal' | 'inline'",
    default: "'modal'",
    description: 'Tipe animasi indikator saat proses pengunggahan berkas berlangsung.'
  },
  {
    name: 'errorText',
    type: 'String',
    default: "''",
    description: 'Pesan kustom yang ditampilkan ketika berkas tidak sesuai kriteria atau melebihi kapasitas.'
  },
  {
    name: '@fileDropped',
    type: 'Event (File)',
    default: '-',
    description: 'Dipancarkan saat pengguna menjatuhkan berkas ke area drag-and-drop atau memilih berkas.'
  },
  {
    name: '@fileRemoved',
    type: 'Event',
    default: '-',
    description: 'Dipancarkan saat pengguna menghapus berkas yang telah dipilih.'
  },
  {
    name: '#footer',
    type: 'Scoped Slot ({ hide })',
    default: '-',
    description: 'Slot kustom tombol aksi persetujuan pada bagian bawah modal pratinjau gambar.'
  }
]
