<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'

// Skenario Kasus Nyata
const activePreset = ref('kca')
const isApproving = ref(false)
const isApproved = ref(false)
const lastAction = ref('Menunggu Persetujuan')
const auditNote = ref('Fisik emas agunan dan identitas e-KTP telah sesuai SOP loket penaksir.')

const scenarioDatasets = {
  kca: {
    sbgNo: 'SBG-2026-JKT-09881',
    nasabah: 'Siti Rahmawati',
    nominal: 'Rp 15.750.000,-',
    produk: 'Gadai Cepat Aman (KCA) Emas Batangan'
  },
  rahn: {
    sbgNo: 'SBG-2026-SYR-04112',
    nasabah: 'Budi Darmawan',
    nominal: 'Rp 25.000.000,-',
    produk: 'Rahn Syariah Karatase 24K'
  },
  krasida: {
    sbgNo: 'SBG-2026-KRA-01948',
    nasabah: 'Ahmad Fauzi',
    nominal: 'Rp 50.000.000,-',
    produk: 'Krasida Angsuran Bulanan Usaha'
  },
  empty: {
    sbgNo: 'SBG-2026-NEW-00000',
    nasabah: 'Menunggu Nasabah...',
    nominal: 'Rp 0,-',
    produk: 'Formulir Gadai Baru'
  }
}

const activeData = computed(() => scenarioDatasets[activePreset.value] || scenarioDatasets.kca)

function applyPreset(preset) {
  activePreset.value = preset
  isApproved.value = false
  if (preset === 'empty') {
    lastAction.value = 'Draf Dikosongkan'
    auditNote.value = 'Formulir SBG baru siap diisi data nasabah pemohon.'
  } else {
    lastAction.value = 'Data Dimuat'
    auditNote.value = `Berkas ${activeData.value.sbgNo} siap diverifikasi dan diotorisasi kasir.`
  }
}

const currentStatusText = computed(() => {
  if (isApproving.value) return 'Sedang Memproses Otorisasi...'
  if (isApproved.value) return 'Persetujuan Diberikan (SBG Siap Cetak)'
  if (lastAction.value === 'Draf Disimpan') return 'Tersimpan Sebagai Draf Loket'
  if (lastAction.value === 'Revisi Diminta') return 'Dalam Proses Revisi Penaksir'
  if (lastAction.value === 'Transaksi Dibatalkan') return 'Transaksi Dibatalkan Kasir'
  return 'Menunggu Tindakan Otorisasi Kasir'
})

const statusClass = computed(() => {
  if (isApproved.value) return 'text-success'
  if (isApproving.value) return 'text-primary'
  if (lastAction.value === 'Transaksi Dibatalkan') return 'text-danger'
  return 'text-dark'
})

const statusBadgeLabel = computed(() => {
  if (isApproved.value) return 'Disetujui'
  if (isApproving.value) return 'Memproses...'
  if (lastAction.value === 'Draf Disimpan') return 'Draf'
  if (lastAction.value === 'Revisi Diminta') return 'Revisi'
  if (lastAction.value === 'Transaksi Dibatalkan') return 'Batal'
  return 'Menunggu'
})

const statusBadgeClass = computed(() => {
  if (isApproved.value) return 'bg-success-subtle text-success border-success-subtle'
  if (isApproving.value) return 'bg-primary-subtle text-primary border-primary-subtle'
  if (lastAction.value === 'Transaksi Dibatalkan') return 'bg-danger-subtle text-danger border-danger-subtle'
  return 'bg-warning-subtle text-warning border-warning-subtle'
})

const lastActionLabel = computed(() => lastAction.value)

function handleBatalTransaksi() {
  isApproved.value = false
  lastAction.value = 'Transaksi Dibatalkan'
  auditNote.value = 'Transaksi dibatalkan oleh kasir. Nomor SBG ditandai void dalam sistem.'
}

function handleRevisiTaksiran() {
  isApproved.value = false
  lastAction.value = 'Revisi Diminta'
  auditNote.value = 'Permintaan revisi nilai karatase diteruskan kembali ke modul penaksir.'
}

function handleSimpanDraf() {
  isApproved.value = false
  lastAction.value = 'Draf Disimpan'
  auditNote.value = 'Data draf berhasil disimpan secara lokal dan aman di server cabang.'
}

function handleSetujuiPinjaman() {
  isApproving.value = true
  lastAction.value = 'Memproses Otorisasi'
  setTimeout(() => {
    isApproving.value = false
    isApproved.value = true
    lastAction.value = 'Pinjaman Disetujui'
    auditNote.value = 'Otorisasi kasir sukses. Surat Bukti Gadai resmi telah diterbitkan dan tercatat pada jurnal buku kas.'
  }, 900)
}

function resetScenarioData() {
  applyPreset('empty')
}

function loadScenarioData() {
  applyPreset('kca')
}

function handleDemoClick(btnName) {
  lastAction.value = `Tombol ${btnName} Diklik`
}

// Props Matrix Documentation
const buttonProps = [
  {
    name: 'label',
    type: 'String',
    default: "''",
    description: 'Teks label yang ditampilkan di dalam tombol.'
  },
  {
    name: 'type',
    type: "'primary' | 'secondary' | 'neutral' | 'tertiary' | 'link'",
    default: "'primary'",
    description: 'Gaya visual semantik tombol sesuai hierarki aksi antarmuka.'
  },
  {
    name: 'size',
    type: "'sm' | 'md' | 'lg' | 'xl'",
    default: "'lg'",
    description: 'Tingkat ukuran tombol: sm (24px), md (40px), lg (48px — bawaan), xl (52px).'
  },
  {
    name: 'loading',
    type: 'Boolean',
    default: 'false',
    description: 'Menampilkan spinner pemrosesan dan menonaktifkan interaksi klik selama proses berjalan.'
  },
  {
    name: 'icon',
    type: 'Boolean',
    default: 'false',
    description: 'Mengaktifkan slot ikon kustom di sebelah kiri label teks tombol.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi tombol dengan styling visual muted redup.'
  },
  {
    name: '@click',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat pengguna mengklik tombol yang sedang dalam kondisi aktif.'
  },
  {
    name: '#icon',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot untuk menyematkan elemen gambar SVG atau ikon di sisi kiri label.'
  }
]
</script>
