<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputNIK from '@/components/Input/InputNIK.vue'

// Real-world scenario state
const rcNikPemohon = ref('3171021405920001')
const rcNikPenjamin = ref('3171084203950003')

function resetScenarioData() {
  rcNikPemohon.value = ''
  rcNikPenjamin.value = ''
}

function loadScenarioData() {
  rcNikPemohon.value = '3201015508880002'
  rcNikPenjamin.value = '3201016209900004'
}

function setPersona(nikPemohon, nikPenjamin) {
  rcNikPemohon.value = nikPemohon
  rcNikPenjamin.value = nikPenjamin
}

// Master Wilayah NIK
const provinceMap = {
  '11': 'Aceh', '12': 'Sumatera Utara', '13': 'Sumatera Barat', '14': 'Riau',
  '15': 'Jambi', '16': 'Sumatera Selatan', '17': 'Bengkulu', '18': 'Lampung',
  '19': 'Kep. Bangka Belitung', '21': 'Kepulauan Riau', '31': 'DKI Jakarta',
  '32': 'Jawa Barat', '33': 'Jawa Tengah', '34': 'DI Yogyakarta', '35': 'Jawa Timur',
  '36': 'Banten', '51': 'Bali', '52': 'Nusa Tenggara Barat', '53': 'Nusa Tenggara Timur',
  '61': 'Kalimantan Barat', '62': 'Kalimantan Tengah', '63': 'Kalimantan Selatan',
  '64': 'Kalimantan Timur', '65': 'Kalimantan Utara', '71': 'Sulawesi Utara',
  '72': 'Sulawesi Tengah', '73': 'Sulawesi Selatan', '74': 'Sulawesi Tenggara',
  '75': 'Gorontalo', '76': 'Sulawesi Barat', '81': 'Maluku', '82': 'Maluku Utara',
  '91': 'Papua Barat', '92': 'Papua'
}

const cityMap = {
  '3171': 'DKI Jakarta, Jakarta Pusat',
  '3172': 'DKI Jakarta, Jakarta Utara',
  '3173': 'DKI Jakarta, Jakarta Barat',
  '3174': 'DKI Jakarta, Jakarta Selatan',
  '3175': 'DKI Jakarta, Jakarta Timur',
  '3201': 'Jawa Barat, Kab. Bogor',
  '3271': 'Jawa Barat, Kota Bogor',
  '3273': 'Jawa Barat, Kota Bandung',
  '3275': 'Jawa Barat, Kota Bekasi',
  '3374': 'Jawa Tengah, Kota Semarang',
  '3578': 'Jawa Timur, Kota Surabaya',
  '5171': 'Bali, Kota Denpasar'
}

const monthNames = [
  'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
  'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
]

// Computed e-KYC Dukcapil Decoder
const decodedNik = computed(() => {
  const nik = String(rcNikPemohon.value || '').trim()
  if (!nik) {
    return {
      isValid: false,
      statusBadge: 'Menunggu Input NIK',
      region: 'Belum terisi',
      gender: '-',
      birthDateFormatted: '-',
      age: null,
      isLegalAge: false,
      summaryMessage: 'Silakan masukkan 16 digit NIK pemohon'
    }
  }

  if (nik.length < 16) {
    return {
      isValid: false,
      statusBadge: `Digit Kurang (${nik.length}/16)`,
      region: 'Format NIK belum lengkap',
      gender: '-',
      birthDateFormatted: '-',
      age: null,
      isLegalAge: false,
      summaryMessage: 'NIK belum memenuhi kuota 16 digit angka resmi'
    }
  }

  // Region decode
  const provCode = nik.substring(0, 2)
  const cityCode = nik.substring(0, 4)
  const region = cityMap[cityCode] || (provinceMap[provCode] ? `Provinsi ${provinceMap[provCode]}` : 'Wilayah Tidak Dikenal')

  // Gender & Birthdate decode (digits 7-12)
  let rawDay = parseInt(nik.substring(6, 8), 10)
  const rawMonth = parseInt(nik.substring(8, 10), 10)
  const rawYear = parseInt(nik.substring(10, 12), 10)

  let gender = 'Laki-laki'
  let day = rawDay
  if (rawDay > 40) {
    gender = 'Perempuan'
    day = rawDay - 40
  }

  // Determine full year
  const current2DigitYear = 26
  const fullYear = rawYear > current2DigitYear ? 1900 + rawYear : 2000 + rawYear
  const monthName = monthNames[rawMonth - 1] || 'Unknown'
  const birthDateFormatted = `${String(day).padStart(2, '0')} ${monthName} ${fullYear}`

  const age = 2026 - fullYear
  const isLegalAge = age >= 17

  return {
    isValid: true,
    statusBadge: '16 Digit Valid Dukcapil',
    region,
    gender,
    birthDateFormatted,
    age,
    isLegalAge,
    summaryMessage: isLegalAge
      ? 'Identitas Nasabah Memenuhi Syarat Legalitas OJK'
      : 'Nasabah Belum Cukup Umur Sesuai Ketentuan OJK (< 17 Thn)'
  }
})

// Lifecycle states
const stateDefault = ref('')
const stateFilled = ref('3171021405920001')
const stateError = ref('31710214')

// Props Matrix Documentation
const nikProps = [
  {
    name: 'modelValue',
    type: 'String | Number',
    default: "''",
    description: 'Nilai 16 digit NIK mentah tanpa spasi yang diikat via v-model.'
  },
  {
    name: 'label',
    type: 'String',
    default: "''",
    description: 'Teks judul label formal di atas kolom input.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "''",
    description: 'Teks petunjuk format pengisian kolom saat kosong.'
  },
  {
    name: 'type',
    type: 'String',
    default: "'text'",
    description: "Tipe mode input: gunakan 'nik' untuk mengaktifkan pemformatan spasi 4 digit."
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi pengguna pada input NIK.'
  },
  {
    name: 'required',
    type: 'Boolean',
    default: 'false',
    description: 'Menandai kolom wajib diisi pada formulir registrasi.'
  },
  {
    name: 'error',
    type: 'String',
    default: "''",
    description: 'Pesan kesalahan validasi di bawah input yang memicu garis batas merah.'
  },
  {
    name: 'helperText',
    type: 'String',
    default: "''",
    description: 'Teks panduan atau informasi tambahan di bawah input.'
  },
  {
    name: 'color',
    type: 'String',
    default: "'default'",
    description: 'Varian aksen tema visual kontrol input.'
  },
  {
    name: 'useDelimiter',
    type: 'Boolean',
    default: 'true',
    description: 'Mengaktifkan pemformatan delimiter spasi otomatis.'
  },
  {
    name: '#label-icon',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot icon penjelasan di samping label NIK.'
  },
  {
    name: '#prefix',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot konten/icon prefix di sisi kiri input (default: icon pencarian NIK).'
  },
  {
    name: '#suffix',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot ornamen/tombol di sisi kanan input.'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat NIK diketik, menghasilkan 16 digit angka murni unformatted.'
  }
]
</script>
