  { id: 'cp_cikini', label: 'CP Cikini Menteng' },
  { id: 'cp_senen', label: 'CP Senen Stasiun' }
]

const scenarioKanwilLabel = computed(() => {
  const found = kanwilItems.find(k => k.id === scenarioKanwil.value)
  return found ? found.label : '-'
})

const scenarioCabangLabel = computed(() => {
  const found = sampleCabangList.find(c => c.id === scenarioCabang.value)
  return found ? found.label : '-'
})

