<script setup>
defineOptions({
  name: 'TimePickerSection'
})
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import TimePicker from '@/components/Input/TimePicker.vue'

// Real-world scenario state
const rcJamBuka = ref('08:00')
const rcJamCutoff = ref('14:30')

function resetScenarioData() {
  rcJamBuka.value = ''
  rcJamCutoff.value = ''
}

function loadScenarioData() {
  rcJamBuka.value = '08:00'
  rcJamCutoff.value = '15:00'
}

function setQuickShift(buka, cutoff) {
  rcJamBuka.value = buka
  rcJamCutoff.value = cutoff
}

const calculatedShiftDuration = computed(() => {
  if (!rcJamBuka.value || !rcJamCutoff.value) return 'Belum dapat dihitung'
  const parseTime = (t) => {
    const parts = t.replace('.', ':').split(':')
    return parseInt(parts[0], 10) * 60 + parseInt(parts[1] || '0', 10)
  }
  const startMins = parseTime(rcJamBuka.value)
  const endMins = parseTime(rcJamCutoff.value)
  const diff = endMins - startMins
  if (diff <= 0) return 'Jam cutoff harus lebih besar dari jam buka'
  const hours = Math.floor(diff / 60)
  const mins = diff % 60
  return `${hours} Jam ${mins > 0 ? `${mins} Menit` : ''}`
})

// Lifecycle states
const stateDefault = ref('')
const statePreselected = ref('15:00')
const stateDisabled = ref('23:59')
const timePickerGlobal = ref('17:00')

// Props Matrix Documentation
const timePickerProps = [
  {
    name: 'v-model:timepicker',
    type: 'String (HH.mm)',
    default: "''",
    description: 'Nilai data waktu yang terpilih (two-way binding via defineModel / custom model).'
  },
  {
    name: 'label',
    type: 'String',
    default: "''",
    description: 'Label teks utama yang diletakkan di atas kolom input pemilih waktu.'
  },
  {
    name: 'label-time',
    type: 'String',
    default: "''",
    description: 'Label spesifik konteks waktu (misal: "Waktu Akhir") yang otomatis menjadi teks placeholder jika placeholder kosong.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "''",
    description: 'Teks instruksi panduan sebelum pengguna menentukan waktu.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi pemilih waktu dan menerapkan visual teredam.'
  },
  {
    name: 'required',
    type: 'Boolean',
    default: 'false',
    description: 'Menandai bahwa input pemilih waktu wajib diisi pada formulir.'
  }
]
</script>
